let project,step=0,role=new URLSearchParams(location.search).get('role')==='adviser'?'adviser':'customer',roomId=D.geometry.geometry.rooms[0].id,taskId='',cursor=null,view,playing=null,photoIndex=0,matchingRoom=undefined,matchingOpen=false,matchingAll=false,siteSide='rear',siteMode='prefer',roomStage=0,roomPhoto=0;
