document.body.innerHTML=`<header class="journey-header"><a class="brand" href="index.html?property=3broomroad&mode=ashp">kelp<span>3 Broom Road</span></a><span class="status">Your heat pump · working together</span><div class="role-switch" aria-label="Workspace"><button data-role="customer" aria-pressed="true">Homeowner</button><button data-role="adviser" aria-pressed="false">Adviser & surveyor</button></div></header><div id="journey-message" role="status" aria-live="polite"></div><nav id="journey-nav" aria-label="Installation journey"></nav><main class="journey-main"><section class="journey-conversation"><div id="journey-content"></div><div class="next-row"><button id="journey-back">Back</button><button id="journey-next" class="primary">See your plan →</button></div></section><aside class="journey-aside"><div id="journey-context"></div><details id="model-detail"><summary id="route-title">Explore the house and possible route</summary><div class="visual-heading"><span>Recorded geometry</span><div><button id="house-front">Front</button><button id="house-rear">Rear</button></div></div><div id="house-view"></div><p id="route-caption" class="subtle"></p></details><div id="journey-next-check"></div></aside></main><footer><span id="journey-revision"></span><a href="replay.html">Geometry & source evidence ↗</a><a href="proposal.html?view=technical">Technical workbench ↗</a><button id="journey-summary">Save homeowner recap</button><button id="journey-export">Export full project</button><label class="import">Import project<input id="journey-import" type="file" accept="application/json" hidden></label></footer>`;
