function photo(id,bbox){const im=window.IMAGE_DATA.images.find(i=>i.id===id)||(window.IMAGE_DATA.floorplan?.id===id?window.IMAGE_DATA.floorplan:null);if(!im)return '';return `<div class="journey-photo"><img src="${esc(SolarViz.imageUrl(im))}" alt="${esc(im.caption||im.room||'Property listing evidence')}"/>${bbox?`<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><rect x="${bbox[0]*100}" y="${bbox[1]*100}" width="${bbox[2]*100}" height="${bbox[3]*100}"/></svg>`:''}<span>Source photograph · listing evidence</span></div>`;}
