const input=(id,label,value='',type='text',attrs='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
function message(text){$('journey-message').textContent=text;if($('matching-message'))$('matching-message').textContent=text;document.querySelectorAll('.evidence-status').forEach(el=>el.textContent=text);}
function commit(next,refresh=true){try{S.save(next);project=next;cursor=null;if(refresh)render();else $('journey-revision').textContent='Saved locally · evidence '+D.revision.slice(0,8)+' · '+project.events.length+' changes';message('Saved on this device. The plan and change history are up to date.');return true;}catch(e){message(e.name==='QuotaExceededError'?'This device’s storage is full. The change has not been saved. Export your current project as a backup, then try smaller photos.':e.message);return false;}}
